pragma solidity ^0.8.20;

// Two shapes a value-out probe has to be able to reach, neither of them specific
// to any protocol: a batch payout whose entire body sits inside a loop over a
// caller-supplied array, and an arbitrary-call executor that forwards
// caller-supplied calldata to a caller-supplied target. A probe that leaves
// either array at the encoder's empty default executes, moves nothing, and
// learns nothing about the body it never entered.
//
// Deployed twice by the test: one instance is the contract under probe, the
// other is the token it holds, so the executor has something real to move.
contract BatchExecutorVault {
    mapping(address => uint256) public balanceOf;

    event Transfer(address indexed from, address indexed to, uint256 value);

    function transfer(address to, uint256 amount) external returns (bool) {
        balanceOf[msg.sender] -= amount;
        balanceOf[to] += amount;
        emit Transfer(msg.sender, to, amount);
        return true;
    }

    // Moves value ONLY per array element; an empty array is a successful no-op.
    function batchPay(uint256[] calldata amounts, address[] calldata recipients) external {
        for (uint256 i; i < recipients.length; ++i) {
            balanceOf[address(this)] -= amounts[i];
            balanceOf[recipients[i]] += amounts[i];
            emit Transfer(address(this), recipients[i], amounts[i]);
        }
    }

    function forward(address target, bytes calldata data, uint256 value) external {
        (bool ok, ) = target.call{value: value}(data);
        require(ok, "inner call failed");
    }

    function forward(address[] calldata targets, bytes[] calldata data, uint256[] calldata values) external {
        for (uint256 i; i < targets.length; ++i) {
            (bool ok, ) = targets[i].call{value: values[i]}(data[i]);
            require(ok, "inner call failed");
        }
    }

    receive() external payable {}
}
